query:
NODE VALUE `out_degree` SumAgg<INT64> = 0
TABLE `result` { `id` STRING, `degree` INT64 }

MATCH (`src`:`player`)-[`e`:`follow`]->(`dst`:`player`)
PER PATH {
  SET `src`.@`out_degree` += 1
}

MATCH (`p`:`player`)
PER NODE (`p`) {
  EXPORT `p`.`id` AS `id`, `p`.@`out_degree` AS `degree` INTO `result`
}

FOR `r` IN `result`
RETURN `r`.`id` AS `id`, `r`.`degree` AS `degree`
